package com.quantumff.segue.core.database.util

import com.quantumff.segue.core.model.ArtistRef
import com.quantumff.segue.core.model.DiscTitle
import kotlinx.serialization.Serializable
import kotlinx.serialization.builtins.ListSerializer
import kotlinx.serialization.builtins.MapSerializer
import kotlinx.serialization.builtins.serializer
import kotlinx.serialization.json.Json

/**
 * JSON encoding for list and map columns. Kept apart from [Converters] because Room's KSP pass
 * cannot see serializers generated by the serialization compiler plugin.
 */
internal object JsonColumns {
    private val json = Json { ignoreUnknownKeys = true }
    private val artistRefs = ListSerializer(StoredArtistRef.serializer())
    private val discTitles = ListSerializer(StoredDiscTitle.serializer())
    private val extensions = MapSerializer(String.serializer(), ListSerializer(Int.serializer()))

    fun encodeArtistRefs(value: List<ArtistRef>): String =
        json.encodeToString(artistRefs, value.map { StoredArtistRef(it.id, it.name) })

    fun decodeArtistRefs(value: String): List<ArtistRef> =
        json.decodeFromString(artistRefs, value).map { ArtistRef(it.id, it.name) }

    fun encodeDiscTitles(value: List<DiscTitle>): String =
        json.encodeToString(discTitles, value.map { StoredDiscTitle(it.disc, it.title) })

    fun decodeDiscTitles(value: String): List<DiscTitle> =
        json.decodeFromString(discTitles, value).map { DiscTitle(it.disc, it.title) }

    fun encodeExtensions(value: Map<String, List<Int>>): String = json.encodeToString(extensions, value)

    fun decodeExtensions(value: String): Map<String, List<Int>> = json.decodeFromString(extensions, value)

    @Serializable
    private data class StoredArtistRef(val id: String, val name: String)

    @Serializable
    private data class StoredDiscTitle(val disc: Int, val title: String)
}
